  }
}];

const source = $('Prepare Action').item.json || {};
const rows = $input.all().map((item) => item.json || {}).filter((item) => item.id || item.name);
if (!rows.length) {
  return [{ json: { ...source, spreadsheetId: '', sheetId: '', targetId: source.targetId || '', targetName: source.targetName || source.sheetName || '', response: 'Khong tim thay Google Sheet phu hop.' } }];
}
const sheet = rows[0];
return [{ json: { ...source, spreadsheetId: sheet.id || source.spreadsheetId || source.targetId || '', sheetId: sheet.id || source.sheetId || source.targetId || '', targetId: source.targetId || sheet.id || source.spreadsheetId || source.sheetId || '', sheetName: sheet.name || source.sheetName || source.targetName || '', targetName: source.targetName || sheet.name || source.sheetName || '', fileName: source.fileName || source.sheetName || source.targetName || sheet.name || '', webViewLink: sheet.webViewLink || '' } }];

const source = $('Prepare Action').item.json || {};
const item = $input.item.json || {};
const sheetId = item.id || source.spreadsheetId || '';
const sheetName = item.name || source.targetName || source.sheetName || 'Không rõ tên';
const link = item.webViewLink || source.webViewLink || (sheetId ? `https://docs.google.com/spreadsheets/d/${sheetId}/edit` : '');

let text = `Đã đưa Google Sheet vào thùng rác: ${sheetName}`;
if (sheetId) text += `\nID: ${sheetId}`;
if (link) text += `\nMở bảng tính: ${link}`;

return [{ json: { chatId: source.chatId || '', text: text.trim() } }];

const source = $json || {};

function decodeEntities(value = '') {
  return String(value)
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'");
}

function htmlToPlainText(value = '') {
  return decodeEntities(String(value || ''))
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<li>/gi, '- ')
    .replace(/<\/h\d>/gi, '\n')
    .replace(/<a[^>]*href="([^"]+)"[^>]*>(.*?)<\/a>/gi, '$2: $1')
    .replace(/<[^>]+>/g, ' ')
    .replace(/[ \t]+/g, ' ')
    .replace(/\s+([,.;:!?])/g, '$1')
    .replace(/\n\s+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const target =
  source.query ||
  source.docName ||
  source.sheetName ||
  source.fileName ||
  source.folderName ||
  source.targetName ||
  source.title ||
  source.summary ||
  source.rawText ||
  source.text ||
  '';

let text = htmlToPlainText(source.response || source.text || source.error || '');
if (!text) {
  text = target
    ? `Mia chưa xử lý được yêu cầu với "${target}". Bạn kiểm tra lại thông tin đầu vào giúp Mia nhé.`
    : 'Mia chưa đủ thông tin để xử lý yêu cầu này.';
}

return [{
  json: {
    ok: false,
    tool: source.tool || source.workflowKey || '',
    chatId: source.chatId || '',
    text,
    links: [],
    result: {},
    meta: {
      target: String(target || '').trim(),
